# ============================================================
# TESTING — pytest (industry standard)
# ============================================================
import pytest
from unittest.mock import Mock, patch, MagicMock
from dataclasses import dataclass

# --- Code to Test ---
@dataclass
class User:
    name: str
    email: str

class UserService:
    def __init__(self, db_repo, email_service):
        self.db = db_repo
        self.email = email_service

    def create_user(self, name: str, email: str) -> User:
        if not email or "@" not in email:
            raise ValueError("Invalid email")
        user = User(name=name, email=email)
        self.db.save(user)
        self.email.send_welcome(user)
        return user

# --- Basic Tests ---
class TestUserService:
    def setup_method(self):
        """Runs before each test."""
        self.mock_db = Mock()
        self.mock_email = Mock()
        self.service = UserService(self.mock_db, self.mock_email)

    def test_create_user_success(self):
        user = self.service.create_user("Veera", "veera@test.com")
        assert user.name == "Veera"
        assert user.email == "veera@test.com"
        self.mock_db.save.assert_called_once_with(user)
        self.mock_email.send_welcome.assert_called_once_with(user)

    def test_create_user_invalid_email(self):
        with pytest.raises(ValueError, match="Invalid email"):
            self.service.create_user("Veera", "bad-email")
        self.mock_db.save.assert_not_called()

# --- Fixtures ---
@pytest.fixture
def sample_user():
    return User(name="Test", email="test@test.com")

@pytest.fixture
def user_service():
    return UserService(db_repo=Mock(), email_service=Mock())

def test_with_fixture(sample_user):
    assert sample_user.name == "Test"

# --- Parametrized Tests ---
@pytest.mark.parametrize("email,valid", [
    ("user@test.com", True),
    ("bad-email", False),
    ("", False),
    ("user@domain.co.uk", True),
])
def test_email_validation(email, valid):
    service = UserService(Mock(), Mock())
    if valid:
        service.create_user("Test", email)
    else:
        with pytest.raises(ValueError):
            service.create_user("Test", email)

# --- Mocking external dependencies ---
@patch("module.requests.get")
def test_api_call(mock_get):
    mock_get.return_value.status_code = 200
    mock_get.return_value.json.return_value = {"data": "test"}
    # Call function that uses requests.get
    # Assert results

# --- Async Tests ---
@pytest.mark.asyncio
async def test_async_function():
    result = await some_async_function()
    assert result == expected_value
